import{_ as r,c as o,o as e,ag as d}from"./chunks/framework._xRlcm3f.js";const P=JSON.parse('{"title":"WordPress 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/wordpress-wordpress.md","filePath":"platforms/wordpress-wordpress.md","lastUpdated":1790228279000}'),a={name:"platforms/wordpress-wordpress.md"};function s(l,t,i,n,p,h){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="wordpress-配置指南" tabindex="-1">WordPress 配置指南 <a class="header-anchor" href="#wordpress-配置指南" aria-label="Permalink to &quot;WordPress 配置指南&quot;">​</a></h1><p>通过 <strong>XML-RPC</strong> 发布到自建/托管 WordPress。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个 WordPress 站点（含管理员账号）。</li><li>一个 <strong>应用程序密码</strong>（Application Password，推荐；也可用账号密码）。</li></ol><h2 id="二、获取应用程序密码" tabindex="-1">二、获取应用程序密码 <a class="header-anchor" href="#二、获取应用程序密码" aria-label="Permalink to &quot;二、获取应用程序密码&quot;">​</a></h2><p>WordPress 后台 → 用户 → 编辑 → 滚动到「应用程序密码」→ 生成。地址：<code>https://你的站点/wp-admin/profile.php</code></p><h2 id="三、配置" tabindex="-1">三、配置 <a class="header-anchor" href="#三、配置" aria-label="Permalink to &quot;三、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>站点首页，如 <code>https://yourblog.com</code></td></tr><tr><td>API 地址</td><td>通常自动推导为 <code>https://yourblog.com/xmlrpc.php</code></td></tr><tr><td>用户名</td><td>WordPress 管理员用户名</td></tr><tr><td>密码</td><td>账号密码；建议用后台生成的<strong>应用程序密码</strong></td></tr><tr><td>预览规则</td><td>默认 <code>/?p=[postid]</code>，与默认固定链接一致，一般不改</td></tr><tr><td>发布格式</td><td>默认 <strong>HTML</strong>（插件先把笔记转成 HTML 再提交）；选 Markdown 则提交 Markdown 原文</td></tr><tr><td>图床服务</td><td>默认「当前平台」：经 XML-RPC 上传到 WordPress 媒体库；也可改选「PicGo 强烈推荐」用你配置的 PicGo；「不使用」跳过图片处理、按原图地址引用（需公网可访问）</td></tr></tbody></table><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 通过后保存。</li><li>快速发布 → 选 WordPress → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>XML-RPC 被禁用</strong>：检查 WordPress 是否开启 XML-RPC，安全插件是否拦截 <code>/xmlrpc.php</code>。</li><li><strong>应用程序密码在哪</strong>：后台 → 用户 → 编辑 → 应用程序密码 → 生成。</li><li><strong>图片上传失败</strong>：确认「图床服务」选的是「当前平台」（经 XML-RPC 上传到 WordPress 媒体库）、站点媒体库权限和网络连通；也可改用「PicGo 强烈推荐」。</li></ul>',12)])])}const m=r(a,[["render",s]]);export{P as __pageData,m as default};
